class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def inorder_traversal(node):
    if not node:
        return []
    return inorder_traversal(node.left) + [node] + inorder_traversal(node.right)

def sum_greater(node, root):
    total = 0
    stack = [(root, False)]
    while stack:
        current, visited = stack.pop()
        if current:
            if visited:
                if current.val > node.val:
                    total += current.val
            else:
                stack.append((current.right, False))
                stack.append((current, True))
                stack.append((current.left, False))
    return total

def transformTree(root):
    def reverse_inorder(node, acc):
        if not node:
            return acc
        acc = reverse_inorder(node.right, acc)
        node.val = acc
        acc = reverse_inorder(node.left, node.val)
        return acc
    reverse_inorder(root, 0)
